export class Object3D {
  constructor() {
    this.position = { 
      set: (x, y, z) => { this.position.x = x; this.position.y = y; this.position.z = z; return this.position; },
      copy: (v) => { this.position.x = v.x; this.position.y = v.y; this.position.z = v.z; return this.position; },
      clone: () => ({ x: this.position.x, y: this.position.y, z: this.position.z }),
      x: 0, y: 0, z: 0 
    };
    this.scale = { 
      set: (x, y, z) => { this.scale.x = x; this.scale.y = y; this.scale.z = z; return this.scale; },
      x: 1, y: 1, z: 1 
    };
    this.rotation = { set: (x, y, z) => { this.rotation.x = x; this.rotation.y = y; this.rotation.z = z; }, x: 0, y: 0, z: 0 };
    this.matrix = {};
    this.updateMatrix = () => {};
  }
}
