export class Quaternion {
  constructor(x = 0, y = 0, z = 0, w = 1) { this.x = x; this.y = y; this.z = z; this.w = w; }
  setFromEuler() { return this; }
  setFromAxisAngle() { return this; }
  premultiply() { return this; }
  copy(q) { this.x = q.x; this.y = q.y; this.z = q.z; this.w = q.w; return this; }
}
export class ShaderMaterial {
  constructor(p = {}) {
    this.uniforms = p.uniforms || {};
    this.vertexShader = p.vertexShader || '';
    this.fragmentShader = p.fragmentShader || '';
    this.transparent = p.transparent || false;
    this.depthWrite = p.depthWrite !== undefined ? p.depthWrite : true;
    this.side = p.side || 0;
  }
  clone() { return new ShaderMaterial(this); }
  dispose() {}
}
