export class Group extends Object3D {
  constructor() {
    super();
    this.children = [];
    this.parent = null;
    this.userData = {};
    this.visible = true;
  }
  add(...objs) {
    for (const c of objs) {
      if (c) {
        c.parent = this;
        this.children.push(c);
      }
    }
  }
  remove(c) {
    const idx = this.children.indexOf(c);
    if (idx !== -1) {
      this.children.splice(idx, 1);
      if (c) c.parent = null;
    }
  }
  traverse(cb) {
    cb(this);
    for (const c of [...this.children]) {
      if (c && typeof c.traverse === 'function') {
        c.traverse(cb);
      } else if (c) {
        cb(c);
      }
    }
  }
}
